package br.com.doceencanto;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.test.context.support.WithMockUser;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import org.springframework.transaction.annotation.Transactional;import java.math.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:teste;DB_CLOSE_DELAY=-1","app.senha=teste-seguro"}) @AutoConfigureMockMvc @Transactional class GestaoTest {
 @Autowired Gestao g;@Autowired MockMvc mvc;
 BigDecimal b(String s){return new BigDecimal(s);}
 Produto produto(){var p=new Produto();p.setNome("Chocolate");p.setPerda(BigDecimal.ZERO);p.setMaoObra(b("120"));p.setEmbalagem(BigDecimal.ONE);g.produto(p);var i=new Ingrediente();i.setProdutoId(p.getId());i.setNome("Ingrediente exemplo");g.ingrediente(i);return p;}
 @Test void margemEArredondamento(){var p=produto();assertEquals(b("16.93"),Calculo.sugerido(p,g.itens(p.getId())));assertEquals(b("132.00"),g.custoBolo(p));assertEquals(b("11.00"),g.custoFatia(p));assertEquals(b("61.00"),g.lucroSugeridoBolo(p));p.setTaxa(b("70"));assertThrows(IllegalArgumentException.class,()->g.produto(p));}
 @Test void financeiroEstoqueESobras(){var p=produto();var e=new Evento();e.setNome("Feira");g.eventosRepo().save(e);g.lote(e.getId(),p.getId(),1,b("20"));var d=new Despesa();d.setEventoId(e.getId());d.setDescricao("Transporte");d.setValor(b("30"));g.despesasRepo().save(d);var l=g.lotes(e.getId()).get(0);g.venda(l.getId(),6,b("20"));var r=g.resumo(e.getId());assertEquals(b("162.00"),r.get("investimento"));assertEquals(b("66.00"),r.get("lucroPrevisto"));assertEquals(b("-48.00"),r.get("lucroReal"));assertEquals("9",r.get("equilibrio"));assertEquals(6,r.get("saldo"));assertThrows(IllegalArgumentException.class,()->g.venda(l.getId(),7,b("20")));e.setEncerrado(true);assertThrows(IllegalArgumentException.class,()->g.venda(l.getId(),1,b("20")));}
 @Test @WithMockUser void telasECsrf()throws Exception{var p=produto();var e=new Evento();e.setNome("Feira");g.eventosRepo().save(e);g.lote(e.getId(),p.getId(),1,b("20"));for(var url:new String[]{"/","/produtos","/produtos/"+p.getId(),"/eventos/novo","/eventos/"+e.getId()})mvc.perform(get(url)).andExpect(status().isOk());mvc.perform(post("/produtos")).andExpect(status().isForbidden());mvc.perform(post("/produtos").with(csrf()).param("nome","Novo")).andExpect(status().is3xxRedirection());}
 @Test void protegeLogin()throws Exception{mvc.perform(get("/")).andExpect(status().is3xxRedirection()).andExpect(redirectedUrlPattern("**/login"));mvc.perform(get("/login")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("Acesse sua gestão")));mvc.perform(get("/style.css")).andExpect(status().isOk());mvc.perform(get("/images/logo-doce-encanto.png")).andExpect(status().isOk());}
 @Test void producaoUsaBancoPersistente()throws Exception{var props=new java.util.Properties();try(var in=getClass().getResourceAsStream("/application.properties")){assertNotNull(in);props.load(in);}var url=props.getProperty("spring.datasource.url");assertTrue(url.startsWith("jdbc:h2:file:"));assertTrue(url.contains("WRITE_DELAY=0"));assertEquals("update",props.getProperty("spring.jpa.hibernate.ddl-auto"));assertEquals("graceful",props.getProperty("server.shutdown"));}
}
